// Generated by esquadro: do not edit. A cell changed in the list itself:
// a choice or a checkbox saves at once; text opens on a click, and saves on
// Enter or on leaving it (Esc gives up). It changes that field alone
// (PATCH), on the version shown (If-Match).
import { useMutation, useQueryClient } from "@tanstack/react-query"
import { Pencil } from "lucide-react"
import { useRef, useState } from "react"
import { Checkbox } from "@/components/ui/checkbox"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Spinner } from "@/components/ui/spinner"
import { api } from "../api.ts"
import { describe, fieldErrors, fieldMessage } from "./errors.ts"
import { capitalize, format, t } from "./i18n.ts"
import type { FieldMeta, Rec, ResourceMeta } from "./meta.ts"
import { FieldValue } from "./show.tsx"
import { toast } from "./toast.tsx"

const NONE = "__none"

export function EditableCell({ meta, field, record }: { meta: ResourceMeta; field: FieldMeta; record: Rec }) {
  const queryClient = useQueryClient()
  const [editing, setEditing] = useState(false)
  const [draft, setDraft] = useState("")
  // Enter saves, and the input's blur after it must not save again.
  const committed = useRef(false)
  const canEdit = (record.can ?? []).includes("update")
  const save = useMutation({
    mutationFn: (value: unknown) => meta.api(api as never).patch(record.id, { [field.name]: value }, { ifMatch: record }),
    onSuccess: () => {
      setEditing(false)
      toast(t("saved"))
      queryClient.invalidateQueries({ queryKey: [meta.name] })
    },
    onError: (e) => {
      committed.current = false
      const code = fieldErrors(e)[field.name]
      toast(code ? `${field.label}: ${fieldMessage(field, code)}` : describe(e), "error")
    },
  })
  if (!canEdit) return <FieldValue field={field} record={record} />
  const stop = { onClick: (e: React.MouseEvent) => e.stopPropagation() }
  const value = record[field.name]

  if (field.kind === "bool") {
    return (
      <div {...stop} className="flex items-center gap-2">
        <Checkbox checked={Boolean(value)} disabled={save.isPending} onCheckedChange={(c) => save.mutate(c === true)} aria-label={field.label} />
        {save.isPending && <Spinner />}
      </div>
    )
  }
  if (field.kind === "enum") {
    return (
      <div {...stop}>
        <Select
          value={value ? String(value) : NONE}
          disabled={save.isPending}
          onValueChange={(v) => save.mutate(v === NONE ? null : v)}
        >
          <SelectTrigger size="sm" className="h-7 w-auto min-w-28 border-transparent bg-transparent shadow-none hover:border-input" aria-label={field.label}>
            <SelectValue />
          </SelectTrigger>
          <SelectContent position="popper">
            {!field.required && <SelectItem value={NONE}>{capitalize(t("none"))}</SelectItem>}
            {field.values?.map((v) => (
              <SelectItem key={v} value={v}>
                {format(field, v)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
    )
  }
  if (editing) {
    const commit = () => {
      if (committed.current) return
      committed.current = true
      const v = draft === "" ? null : field.kind === "int" ? Number(draft) : draft
      if (v === (value ?? null) || String(v) === String(value)) setEditing(false)
      else save.mutate(v)
    }
    return (
      <div {...stop} className="flex items-center gap-2">
        <Input
          autoFocus
          className="h-7 w-32"
          value={draft}
          disabled={save.isPending}
          type={field.kind === "int" ? "number" : "text"}
          inputMode={field.kind === "decimal" ? "decimal" : undefined}
          onChange={(e) => setDraft(e.target.value)}
          onBlur={commit}
          onKeyDown={(e) => {
            if (e.key === "Enter") commit()
            if (e.key === "Escape") {
              committed.current = true
              setEditing(false)
            }
          }}
          aria-label={field.label}
        />
        {save.isPending && <Spinner />}
      </div>
    )
  }
  return (
    <button
      type="button"
      className="group/cell -mx-2 flex items-center gap-2 rounded-md px-2 py-1 text-left hover:bg-muted"
      onClick={(e) => {
        e.stopPropagation()
        committed.current = false
        setDraft(value === null || value === undefined ? "" : String(value))
        setEditing(true)
      }}
      aria-label={`${t("edit")} ${field.label}`}
    >
      <FieldValue field={field} record={record} />
      <Pencil className="size-3 text-muted-foreground opacity-0 transition-opacity group-hover/cell:opacity-100" />
    </button>
  )
}
